sys_ui_action.script:
var valid=true;
if (current.hr_service.value == "internal_safety_complaint") {
    if (current.whsc_comments == ""){gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.whsc_comments"));valid=false;}
    if (current.rw_whsc_decision == ""){gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.rw_whsc_decision"));valid=false;}
	if (current.whsc_user == ""){gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.whsc_user"));valid=false;}

    current.update();
    action.setRedirectURL(current);
    if (valid==true) {
		createEmployeeTaskRecord(); // Create RP stage II
        createManagerTaskRecord();
        current.state = 108;
    }
	current.update();
    action.setRedirectURL(current);
}

if (current.hr_service.value == "refusal_to_work") {
    if (current.investigation_conducted_by_employer == ""){gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.investigation_conducted_by_employer"));valid=false;}
    if (current.whsc_user == "") {gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.whsc_user"));valid=false;}
    if (current.rw_whsc_date_time == "") {gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.rw_whsc_date_time"));valid=false;}
    if (current.employer_wpcmember == "") {gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.employer_wpcmember"));valid=false;}
    if (current.rw_agree_emply_dec == "") {gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.rw_agree_emply_dec"));valid=false;}
    if (current.employer_rep_investigation_report_provided_to_employer_date == ""){gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.employer_rep_investigation_report_provided_to_employer_date"));valid=false;}
    if (current.employer_rep_investigation_report_provided_to_employer_time == ""){gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.employer_rep_investigation_report_provided_to_employer_time"));valid=false;} //TODO: MEssage does not exist!
    if (current.whsc_comments == ""){gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.whsc_comments"));valid=false;}
	if (current.rw_whsc_decision == ""){gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.rw_whsc_decision"));valid=false;}
	if (current.rw_reco_empl == ""){gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.rw_reco_empl"));valid=false;}
    if (current.employee_rep_investigation_report_provided_to_employer == ""){gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.employee_rep_investigation_report_provided_to_employer"));valid=false;}
	if (current.employee_rep_investigation_report_provided_to_employer_time == ""){gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.employee_rep_investigation_report_provided_to_employer_time"));valid=false;}
	if (current.rw_reco_deta == ""){gs.addErrorMessage(gs.getMessage("x_hccc_hoc_ohs.rw_reco_deta"));valid=false;}

    if (valid == true) {
        current.state = 108;
		createEmployeeTaskRecord();
    }

	current.update();
    action.setRedirectURL(current);
}


function createEmployeeTaskRecord() {
    var grTask = new GlideRecord("sn_hr_core_task");
    grTask.initialize();
    grTask.parent = current.sys_id;
    grTask.hr_task_type = "submit_catalog_item";
    grTask.state = 18;
    grTask.assigned_to = current.subject_person;
    if (current.hr_service.value == "refusal_to_work") {
        grTask.short_description = "Refusal to work employee validation - stage II";
        grTask.sc_cat_item = "e578ccaf2fd72c104cbeb1e72799b6d2"; //Refusal to work employee validation stage II
    } else if (current.hr_service.value == "internal_safety_complaint") {
        grTask.short_description = "Internal Safety Complaint employee validation - stage II";
        grTask.sc_cat_item = "7763286ddbfdbc109b09e6fa4b961904"; //Safety complaint stage II
    }
    grTask.insert();
}

function createManagerTaskRecord() {
    var grTask = new GlideRecord("sn_hr_core_task");
    grTask.initialize();
    grTask.parent = current.sys_id;
    grTask.hr_task_type = "submit_catalog_item";
    grTask.state = 18;
    grTask.assigned_to = current.manager_name;
    grTask.short_description = "Internal Safety Complaint manager validation - stage II";
    grTask.sc_cat_item = "6be588691b1901109fde86acdd4bcbed"; //Safety complaint stage II
    grTask.insert();

}
